const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const doc = (o = {}) => ({ id: 'one', tenant: 'a', owner: 'u', deleted: false, archived: false, ...o });
const actor = (o = {}) => ({ tenant: 'a', user: 'u', role: 'admin', ...o });
const fresh = () => {
  const repo = new DocumentRepository([doc()]);
  const service = new DocumentService(repo);
  return { repo, service };
};

// admin archives any visible document; strangers and self work
{
  const { repo, service } = fresh();
  service.archive(actor({ user: 'u' }), 'one');
  service.archive(actor({ user: 'other' }), 'one');
  assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
  assert.equal(repo.documents[0].archived, true);
}

// viewer never, editor only when owner
{
  const { repo, service } = fresh();
  assert.throws(() => service.archive(actor({ role: 'viewer', user: 'u' }), 'one'), /forbidden/);
  assert.throws(() => service.archive(actor({ role: 'viewer', user: 'other' }), 'one'), /forbidden/);
  assert.throws(() => service.archive(actor({ role: 'editor', user: 'other' }), 'one'), /forbidden/);
  service.archive(actor({ role: 'editor', user: 'u' }), 'one');
  assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
}

// missing, deleted, foreign tenant => 'not found' even for admin
{
  const { service } = fresh();
  assert.throws(() => service.archive(actor(), 'missing'), /not found/);
  const deleted = { repo: null, service: new DocumentService(new DocumentRepository([doc({ deleted: true })])) };
  assert.throws(() => deleted.service.archive(actor(), 'one'), /not found/);
  const foreign = new DocumentService(new DocumentRepository([doc({ tenant: 'b' })]));
  assert.throws(() => foreign.archive(actor(), 'one'), /not found/);
}

// repeat on archived visible doc is a no-op, but permission still enforced first
{
  const { repo, service } = fresh();
  service.archive(actor(), 'one');
  assert.throws(() => service.archive(actor({ role: 'viewer' }), 'one'), /forbidden/); // forbidden despite archived
  service.archive(actor(), 'one'); // no-op
  assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
}

// failures leave documents and audit untouched
{
  const repo = new DocumentRepository([doc(), doc({ id: 'two', owner: 'x' })]);
  const service = new DocumentService(repo);
  for (const [a, id] of [
    [actor({ role: 'viewer' }), 'one'],
    [actor({ role: 'editor', user: 'u' }), 'two'],
    [actor({ tenant: 'b' }), 'one'],
    [actor(), 'missing'],
  ]) assert.throws(() => service.archive(a, id), /not found|forbidden/);
  assert.deepEqual(repo.audit, []);
  assert.deepEqual(repo.documents.map(d => d.archived), [false, false]);
}

console.log('authz ok');

